import {
  SliderControl,
  SliderIndicator,
  Slider as SliderPrimitive,
  SliderThumb,
  SliderTrack,
} from "@ui-sdk/react/slider";
import type { ComponentProps } from "react";

import { cn } from "@/lib/utils";

/** How many thumbs the slider has: one per value, or a range of two. */
function thumbCount(value: unknown, defaultValue: unknown) {
  if (Array.isArray(value)) {
    return value.length;
  }
  if (Array.isArray(defaultValue)) {
    return defaultValue.length;
  }
  return 2;
}

function Slider({
  className,
  defaultValue,
  value,
  min = 0,
  max = 100,
  onValueCommitted,
  ...props
}: ComponentProps<typeof SliderPrimitive> & {
  /** Base UI's name for `onValueCommit`. */
  onValueCommitted?: ComponentProps<typeof SliderPrimitive>["onValueCommit"];
}) {
  // A thumb is known by its place: the first, the second.
  const thumbs = Array.from(
    { length: thumbCount(value, defaultValue) },
    (_, index) => index
  );

  return (
    <SliderPrimitive
      className={cn(
        "data-[orientation=horizontal]:w-full data-[orientation=vertical]:h-full",
        className
      )}
      defaultValue={defaultValue}
      max={max}
      min={min}
      onValueCommit={onValueCommitted}
      value={value}
      {...props}
    >
      <SliderControl className="data-vertical:min-h-40 relative flex w-full touch-none items-center select-none data-disabled:opacity-50 data-[orientation=vertical]:h-full data-[orientation=vertical]:w-auto data-[orientation=vertical]:flex-col">
        <SliderTrack className="bg-input/90 rounded-full data-horizontal:h-2 data-horizontal:w-full data-vertical:h-full data-vertical:w-2 relative grow overflow-hidden select-none">
          <SliderIndicator className="bg-primary select-none data-[orientation=horizontal]:h-full data-[orientation=vertical]:w-full" />
        </SliderTrack>
        {thumbs.map((thumb) => (
          <SliderThumb
            className="ring-black/10 not-dark:bg-clip-padding ring-1 h-4 w-6 rounded-full bg-white shadow-md transition-[color,box-shadow,background-color] hover:ring-4 hover:ring-ring/30 focus-visible:ring-4 focus-visible:ring-ring/30 focus-visible:outline-hidden data-vertical:h-6 data-vertical:w-4 block shrink-0 select-none disabled:pointer-events-none disabled:opacity-50"
            index={thumb}
            key={thumb}
          />
        ))}
      </SliderControl>
    </SliderPrimitive>
  );
}

export { Slider };
